// OMS dashboard. Read-only: this file issues GET requests only.
//
// Two kinds of data are shown and never mixed without a label:
//   - design and verification records generated by `xtask docs` (data/*.json)
//   - what a running node reports (/api/*), built from durable records
// Every live value carries one of four labels: observed, inferred, expected, unknown.
'use strict';

const S = {
  reg: null,
  evidence: null,
  perf: [],
  mutants: null,
  status: null, // last /api/status body, or null
  statusState: 'pending', // pending | none | live | lost
  statusError: '',
  ids: new Map(),
  filter: { layer: '', applicability: '', verify: '', q: '' },
  claimFilter: '',
  ordersScope: 'open',
  liveKey: '',
};

// ---------------------------------------------------------------- DOM helpers

function h(tag, attrs, ...kids) {
  const el = document.createElement(tag);
  if (attrs) {
    for (const [k, v] of Object.entries(attrs)) {
      if (v === null || v === undefined || v === false) continue;
      if (k === 'class') el.className = v;
      else if (k.startsWith('on')) el.addEventListener(k.slice(2), v);
      else if (v === true) el.setAttribute(k, '');
      else el.setAttribute(k, String(v));
    }
  }
  add(el, kids);
  return el;
}

function add(el, kids) {
  for (const k of kids) {
    if (k === null || k === undefined || k === false) continue;
    if (Array.isArray(k)) add(el, k);
    else if (k instanceof Node) el.appendChild(k);
    else el.appendChild(document.createTextNode(String(k)));
  }
}

const KIND = { observed: '관측', inferred: '추론', expected: '기대', unknown: '미확인' };
const tag = (kind) => h('span', { class: 'tag ' + kind }, KIND[kind]);
const badge = (cls, text) => h('span', { class: 'badge ' + cls }, text);

function statusBadge(v) {
  const cls = { 결정: 'ok', 구현: 'ok', 검증: 'ok', 적용: 'ok', 부분: 'warn', 미결: 'warn', 조건부: 'warn', 미구현: 'bad', 미검증: 'bad', 비적용: 'none', 해당없음: 'none' }[v] || 'none';
  return badge(cls, v);
}

const CLAIM_STATUS = { passed: ['ok', '통과'], failed: ['bad', '실패'], not_run: ['none', '미실행'], stale: ['warn', '이전 버전 결과'] };
function claimBadge(st) {
  const [cls, text] = CLAIM_STATUS[st] || ['none', st];
  return badge(cls, text);
}
const RESULT = { passed: ['ok', '통과'], failed: ['bad', '실패'], ignored: ['warn', '건너뜀'], not_run: ['none', '미실행'], stale: ['warn', '이전 버전 결과'] };
function resultBadge(r) {
  const [cls, text] = RESULT[r] || ['none', r];
  return badge(cls, text);
}

function fmtTs(us) {
  if (!us) return '—';
  const d = new Date(us / 1000);
  const p = (n, w = 2) => String(n).padStart(w, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}.${p(Math.floor((us % 1000000) / 1000), 3)}`;
}
function fmtDur(us) {
  if (us === null || us === undefined) return '—';
  if (us < 1000) return `${us} µs`;
  if (us < 1000000) return `${(us / 1000).toFixed(2)} ms`;
  if (us < 120000000) return `${(us / 1000000).toFixed(1)} s`;
  return `${Math.round(us / 60000000)} 분`;
}
const nowUs = () => Date.now() * 1000;
const isTsKey = (k) => /(^|_)(at|since|as_of|up_to|floor|cutoff)$/.test(k) || k === 'expires_at';

// Generic JSON view: nothing is dropped, so an unfamiliar field still shows.
function jv(v, key) {
  if (v === null || v === undefined) return h('span', { class: 'muted' }, '없음');
  if (typeof v === 'number' && key && isTsKey(key) && v > 1e14) return h('span', { title: String(v) }, fmtTs(v));
  if (typeof v !== 'object') return h('span', { class: typeof v === 'string' ? '' : 'mono' }, String(v));
  if (Array.isArray(v)) {
    if (v.length === 0) return h('span', { class: 'muted' }, '없음');
    if (v.every((x) => x === null || typeof x !== 'object')) return h('span', { class: 'mono' }, v.join(', '));
    return h('div', null, v.map((x) => h('div', null, jv(x))));
  }
  const keys = Object.keys(v);
  if (keys.length === 0) return h('span', { class: 'muted' }, '없음');
  return h('dl', { class: 'kv' }, keys.map((k) => [h('dt', null, k), h('dd', null, jv(v[k], k))]));
}
const pre = (v) => h('pre', null, typeof v === 'string' ? v : JSON.stringify(v, null, 2));
function details(key, summary, body) {
  return h('details', { 'data-k': key }, h('summary', null, summary), body);
}

function table(heads, rows, opts) {
  const o = opts || {};
  return h('div', { class: 'tablewrap' },
    h('table', null,
      h('thead', null, h('tr', null, heads.map((x) => h('th', typeof x === 'object' && !(x instanceof Node) ? { class: x.cls } : null, typeof x === 'object' && !(x instanceof Node) ? x.t : x)))),
      h('tbody', null, rows.map((r) => {
        const cells = r.cells || r;
        const tr = h('tr', r.href ? { class: 'click', onclick: () => { location.hash = r.href; } } : null,
          cells.map((c, i) => {
            const head = heads[i];
            const cls = (typeof head === 'object' && !(head instanceof Node) && head.cls) || (o.nowrap && o.nowrap.includes(i) ? 'nowrap' : null);
            return h('td', cls ? { class: cls } : null, c);
          }));
        return tr;
      }))));
}

// ---------------------------------------------------------------- cross links

const ID_RE = /\b(ADR-\d{3}|[GDP]-[A-Z]+-\d{2}|C-[A-Z]+|V-[A-Z]+-\d+|U-\d{2}|A-\d{2})\b/g;

function idLink(id) {
  const route = S.ids.get(id);
  return route ? h('a', { href: route.href, title: route.title }, id) : h('span', null, id);
}
function idLinks(list) {
  if (!list || list.length === 0) return h('span', { class: 'muted' }, '없음');
  return h('span', { class: 'chips' }, list.map((id) => idLink(id)));
}
// Turns known identifiers inside free text into links.
function linkify(text) {
  if (!text) return [];
  const out = [];
  let last = 0;
  for (const m of String(text).matchAll(ID_RE)) {
    if (!S.ids.has(m[1])) continue;
    if (m.index > last) out.push(text.slice(last, m.index));
    out.push(idLink(m[1]));
    last = m.index + m[1].length;
  }
  if (last < text.length) out.push(text.slice(last));
  return out;
}
function inlineText(text) {
  // `code` spans in registry text
  const out = [];
  for (const part of String(text || '').split(/(`[^`]+`)/)) {
    if (part.startsWith('`') && part.endsWith('`') && part.length > 2) out.push(h('code', null, part.slice(1, -1)));
    else out.push(linkify(part));
  }
  return out;
}
const fileLink = (path) => h('a', { class: 'mono', href: '#/doc/' + path }, path);
function fileLinks(list) {
  if (!list || list.length === 0) return h('span', { class: 'muted' }, '없음');
  return h('div', null, list.map((p) => h('div', null, fileLink(p))));
}
const eventChip = (name) => h('a', { class: 'chip', href: '#/event/' + name }, name);
const evName = (e) => (typeof e === 'string' ? e : Object.keys(e)[0]);
const evBody = (e) => (typeof e === 'string' ? null : e[Object.keys(e)[0]]);
// Inputs nest one level (`venue` and `operator` wrap the actual kind); show both.
function inputName(input) {
  const outer = evName(input);
  const inner = evBody(input);
  if ((outer === 'venue' || outer === 'operator') && inner) return `${outer}.${evName(inner)}`;
  return outer;
}

function field(dl, name, value) {
  dl.appendChild(h('dt', null, name));
  dl.appendChild(h('dd', null, value));
}

// ---------------------------------------------------------------- data

async function getJson(url) {
  const r = await fetch(url, { cache: 'no-store' });
  if (!r.ok) {
    const e = new Error(`${url}: HTTP ${r.status}`);
    e.status = r.status;
    throw e;
  }
  return r.json();
}

async function loadStatic() {
  S.reg = await getJson('data/registry.json');
  S.evidence = await getJson('data/evidence.json').catch(() => null);
  S.perf = (await getJson('data/perf.json').catch(() => [])) || [];
  S.mutants = await getJson('data/mutants.json').catch(() => null);
  const R = S.reg;
  for (const c of R.considerations) S.ids.set(c.id, { href: '#/item/' + c.id, title: c.consideration });
  for (const d of R.decisions) S.ids.set(d.id, { href: '#/adr/' + d.id, title: d.title });
  for (const c of R.contracts) S.ids.set(c.id, { href: '#/contract/' + c.id, title: c.title });
  for (const c of R.claims) S.ids.set(c.id, { href: '#/claim/' + c.id, title: c.statement });
  for (const a of R.assumptions) S.ids.set(a.id, { href: '#/assumption/' + a.id, title: a.statement });
  for (const u of R.user_decisions) S.ids.set(u.id, { href: '#/user/' + u.id, title: u.title });
  for (const s of R.sources) S.ids.set(s.id, { href: '#/source/' + s.id, title: s.title });
}

async function pollStatus() {
  try {
    S.status = await getJson('api/status');
    S.statusState = 'live';
    S.statusError = '';
  } catch (e) {
    if (e.status === 503) {
      S.statusState = 'none';
      S.status = null;
    } else {
      // The node answered before and does not now, or this page is not served by a node at all.
      S.statusState = S.statusState === 'live' || S.statusState === 'lost' ? 'lost' : 'none';
      S.statusError = String(e.message || e);
    }
  }
  renderBanner();
}

function runKind() {
  if (S.statusState === 'pending') return ['unknown', '확인 중'];
  if (S.statusState === 'none') return ['docs', '설명용 (노드 없음)'];
  const venue = (S.status && S.status.node && S.status.node.venue) || '';
  if (S.statusState === 'lost') return ['fatal', `노드 응답 없음 (마지막: ${venue})`];
  if (S.status.fatal) return ['fatal', `치명 상태로 정지 (${venue})`];
  if (venue === 'sim') return ['sim', '시뮬레이터 실행 (가상 거래소)'];
  if (venue.endsWith('mainnet')) return ['mainnet', `실제 시스템 · ${venue}`];
  return ['testnet', `실제 시스템 · ${venue}`];
}

function renderBanner() {
  const [cls, text] = runKind();
  const rk = document.getElementById('runkind');
  rk.className = 'runkind ' + cls;
  rk.textContent = text;
  const facts = document.getElementById('bannerfacts');
  facts.replaceChildren();
  const fact = (label, value, alert) => facts.appendChild(h('span', alert ? { class: 'alert' } : null, label + ' ', h('b', null, value)));
  const R = S.reg;
  if (S.status) {
    const st = S.status;
    const age = nowUs() - st.as_of;
    fact('출처', '/api/status');
    fact('기준 시각', fmtTs(st.as_of));
    fact('브라우저와의 차이', fmtDur(Math.abs(age)), S.statusState === 'lost' || Math.abs(age) > 10000000);
    fact('내구 순번', String(st.journal.durable_seq));
    fact('노드 소스', st.node.source_digest);
    if (R && R.source_digest !== st.node.source_digest) {
      fact('문서 소스', R.source_digest + ' — 실행 중인 바이너리와 다르다. 문서가 다른 코드를 설명하고 있을 수 있다', true);
    }
    if (st.fatal) fact('치명 사유', st.fatal, true);
  } else if (R) {
    fact('출처', 'data/registry.json');
    fact('문서 생성', fmtTs(R.generated_at_us));
    fact('문서 소스', R.source_digest);
  }
  if (R) {
    if (!S.evidence) fact('검증 결과', '없음 (수용 시험 미실행)', true);
    else if (S.evidence.source_digest !== R.source_digest) fact('검증 결과 소스', S.evidence.source_digest + ' — 현재 소스와 다르다', true);
    else fact('검증 결과', fmtTs(S.evidence.finished_at_us));
  }
}

// ---------------------------------------------------------------- markdown

function mdInline(text, base) {
  const out = [];
  const re = /(`[^`]+`|\*\*[^*]+\*\*|\[[^\]]+\]\([^)\s]+\))/;
  for (const part of String(text).split(re)) {
    if (!part) continue;
    if (part.startsWith('`') && part.endsWith('`') && part.length > 2) {
      const code = part.slice(1, -1);
      if (/^(crates|docs|registry)\/[\w./-]+\.(rs|md|toml)$/.test(code)) out.push(h('a', { href: '#/doc/' + code }, h('code', null, code)));
      else out.push(h('code', null, code));
    } else if (part.startsWith('**') && part.endsWith('**') && part.length > 4) {
      out.push(h('strong', null, mdInline(part.slice(2, -2), base)));
    } else {
      const m = part.match(/^\[([^\]]+)\]\(([^)\s]+)\)$/);
      if (m) {
        const [, label, target] = m;
        if (/^https?:/.test(target)) out.push(h('a', { href: target, rel: 'noreferrer noopener', target: '_blank' }, label));
        else if (target.startsWith('#')) out.push(h('span', null, label));
        else out.push(h('a', { href: '#/doc/' + resolvePath(base, target.split('#')[0]) }, label));
      } else out.push(linkify(part));
    }
  }
  return out;
}

function resolvePath(base, rel) {
  const parts = base.split('/').slice(0, -1);
  for (const seg of rel.split('/')) {
    if (seg === '..') parts.pop();
    else if (seg !== '.' && seg !== '') parts.push(seg);
  }
  return parts.join('/');
}

function splitRow(line) {
  let s = line.trim();
  if (s.startsWith('|')) s = s.slice(1);
  if (s.endsWith('|')) s = s.slice(0, -1);
  // a pipe inside a code span does not separate cells
  const cells = [];
  let cur = '';
  let inCode = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === '`') inCode = !inCode;
    if (ch === '\\' && s[i + 1] === '|') { cur += '|'; i++; continue; }
    if (ch === '|' && !inCode) { cells.push(cur.trim()); cur = ''; } else cur += ch;
  }
  cells.push(cur.trim());
  return cells;
}

function markdown(text, base) {
  const root = h('div', { class: 'doc' });
  const lines = text.split('\n');
  let i = 0;
  let para = [];
  const flush = () => {
    if (para.length) root.appendChild(h('p', null, mdInline(para.join(' '), base)));
    para = [];
  };
  while (i < lines.length) {
    const line = lines[i];
    if (line.startsWith('```')) {
      flush();
      const buf = [];
      i++;
      while (i < lines.length && !lines[i].startsWith('```')) buf.push(lines[i++]);
      i++;
      root.appendChild(h('pre', null, h('code', null, buf.join('\n'))));
      continue;
    }
    const hm = line.match(/^(#{1,4})\s+(.*)$/);
    if (hm) {
      flush();
      root.appendChild(h('h' + hm[1].length, null, mdInline(hm[2], base)));
      i++;
      continue;
    }
    if (line.trim().startsWith('|') && i + 1 < lines.length && /^\s*\|?[\s:|-]+\|?\s*$/.test(lines[i + 1]) && lines[i + 1].includes('-')) {
      flush();
      const heads = splitRow(line);
      i += 2;
      const rows = [];
      while (i < lines.length && lines[i].trim().startsWith('|')) rows.push(splitRow(lines[i++]));
      root.appendChild(h('div', { class: 'tablewrap' }, h('table', null,
        h('thead', null, h('tr', null, heads.map((c) => h('th', null, mdInline(c, base))))),
        h('tbody', null, rows.map((r) => h('tr', null, r.map((c) => h('td', null, mdInline(c, base)))))))));
      continue;
    }
    const lm = line.match(/^(\s*)([-*]|\d+\.)\s+(.*)$/);
    if (lm) {
      flush();
      const ordered = /\d/.test(lm[2]);
      const list = h(ordered ? 'ol' : 'ul');
      while (i < lines.length) {
        const m = lines[i].match(/^(\s*)([-*]|\d+\.)\s+(.*)$/);
        if (m) {
          list.appendChild(h('li', null, mdInline(m[3], base)));
          i++;
        } else if (/^\s{2,}\S/.test(lines[i]) && list.lastChild) {
          add(list.lastChild, [' ', mdInline(lines[i].trim(), base)]);
          i++;
        } else break;
      }
      root.appendChild(list);
      continue;
    }
    if (line.startsWith('>')) {
      flush();
      const buf = [];
      while (i < lines.length && lines[i].startsWith('>')) buf.push(lines[i++].replace(/^>\s?/, ''));
      root.appendChild(h('blockquote', null, mdInline(buf.join(' '), base)));
      continue;
    }
    if (/^---+\s*$/.test(line)) { flush(); root.appendChild(h('hr')); i++; continue; }
    if (line.trim() === '') { flush(); i++; continue; }
    para.push(line.trim());
    i++;
  }
  flush();
  return root;
}

async function docBlock(path) {
  const box = h('div', null, h('p', { class: 'muted' }, '문서를 불러오는 중'));
  try {
    const r = await fetch('src/' + path, { cache: 'no-store' });
    if (!r.ok) throw new Error('HTTP ' + r.status);
    const text = await r.text();
    box.replaceChildren(path.endsWith('.md') ? markdown(text, path) : pre(text));
  } catch (e) {
    box.replaceChildren(h('div', { class: 'notice none' }, `이 배포에서는 ${path} 를 읽을 수 없다 (${e.message}). 소스 저장소에서 직접 연다.`));
  }
  return box;
}

// ---------------------------------------------------------------- screen 1: considerations and decisions

function itemsTabs(active) {
  const R = S.reg;
  const tabs = [
    ['', `고려사항 ${R.considerations.length}`],
    ['decisions', `설계 결정 ${R.decisions.length}`],
    ['assumptions', `외부 가정 ${R.assumptions.length}`],
    ['user', `사용자 결정 ${R.user_decisions.length}`],
    ['sources', `출처 ${R.sources.length}`],
    ['coverage', `출처 요소별 대응 ${(R.coverage || []).length}`],
  ];
  return h('div', { class: 'tabs' }, tabs.map(([k, t]) => h('a', { href: '#/items' + (k ? '/' + k : ''), class: k === active ? 'active' : null }, t)));
}

function unpassedFor(id) {
  const hit = S.reg.summary.verified_items_with_unpassed_claims.find((x) => x.item === id);
  return hit ? hit.claims_not_passed : null;
}
function verifyBadge(c) {
  const un = c.verify === '검증' ? unpassedFor(c.id) : null;
  if (un) return h('span', { title: '검증으로 적혀 있지만 근거 주장이 현재 통과 상태가 아니다: ' + un.join(', ') }, badge('warn', '검증(근거 미통과)'));
  return statusBadge(c.verify);
}

function screenItems(sub) {
  const R = S.reg;
  const root = h('div', null, h('h1', null, '고려사항과 설계 결정'), itemsTabs(sub || ''));
  if (sub === 'decisions') {
    root.appendChild(table(['ID', '제목', '문제', '선택', '포기한 것', '재검토 조건'],
      R.decisions.map((d) => ({ href: '#/adr/' + d.id, cells: [idLink(d.id), d.title, d.problem, d.chosen, d.gives_up, d.revisit] })), { nowrap: [0] }));
    return root;
  }
  if (sub === 'assumptions') {
    root.appendChild(h('p', { class: 'muted' }, '이 시스템이 스스로 보장하지 못하고 외부에 기대는 것. 깨지면 무엇이 일어나고 어떻게 알아채는지를 함께 적는다.'));
    root.appendChild(table(['ID', '가정', '기대는 대상', '깨지면', '탐지', '확인한 범위'],
      R.assumptions.map((a) => ({ href: '#/assumption/' + a.id, cells: [idLink(a.id), a.statement, a.depends_on, a.if_broken, a.detection, a.checked] })), { nowrap: [0] }));
    return root;
  }
  if (sub === 'user') {
    root.appendChild(h('p', { class: 'muted' }, '사용자가 정해야 하는 것. 정해지기 전까지의 기본값은 각 항목의 영향 칸에 있다.'));
    root.appendChild(table(['ID', '결정', '필요한 이유', '추천', '대안', '영향', '미룰 수 있는 시점'],
      R.user_decisions.map((u) => ({ href: '#/user/' + u.id, cells: [idLink(u.id), u.title, inlineText(u.why), inlineText(u.recommendation), h('ul', null, u.alternatives.map((a) => h('li', null, a))), inlineText(u.impact), u.defer_until] })), { nowrap: [0] }));
    return root;
  }
  if (sub === 'sources') {
    root.appendChild(h('p', { class: 'muted' }, '검토 기준의 출처. 준수나 인증을 주장하는 것이 아니라 누락을 찾기 위한 분류 축으로 쓴다. 읽은 범위를 넘는 내용은 인용하지 않았다.'));
    root.appendChild(table(['ID', '자료', '역할', '판·시점', '읽은 범위', '주의', '상세'],
      R.sources.map((s) => [h('span', { id: 'src-' + s.id }, s.id), s.title, s.role, s.version, s.accessed, [s.caution, s.secondary ? h('div', { class: 'muted small' }, s.secondary) : null], s.detail ? fileLink(s.detail) : '']), { nowrap: [0] }));
    return root;
  }

  if (sub === 'coverage') {
    const rows = R.coverage || [];
    const n = (st) => rows.filter((r) => r.status === st).length;
    const cls = { 다룸: 'ok', 비적용: 'none', 보류: 'warn', 미검토: 'bad' };
    root.appendChild(h('p', { class: 'muted' }, `검토 기준의 모수다. 출처가 나누어 둔 요소 ${rows.length}건: 다룸 ${n('다룸')} · 비적용 ${n('비적용')} · 보류 ${n('보류')} · 미검토 ${n('미검토')}. "다룸"은 검토 항목이 있다는 뜻이고, 구현·검증 여부는 그 항목의 상태를 본다.`));
    root.appendChild(table(['출처', '요소', '상태', '검토 항목', '비고(비적용·미검토의 이유, 보류의 영향과 재개 조건)'],
      rows.map((r) => [idLink(r.source), r.element, badge(cls[r.status] || 'none', r.status), idLinks(r.items), inlineText(r.note)]), { nowrap: [0] }));
    return root;
  }

  const sum = R.summary;
  const counts = (o) => Object.entries(o).map(([k, v]) => `${k} ${v}`).join(' · ');
  root.appendChild(h('div', { class: 'cards' },
    h('div', { class: 'card' }, h('h3', null, '계층'), `일반 ${sum.by_layer.general} · Rust·LMAX·OMS ${sum.by_layer.domain} · 프로젝트 ${sum.by_layer.project}`),
    h('div', { class: 'card' }, h('h3', null, '설계'), counts(sum.design)),
    h('div', { class: 'card' }, h('h3', null, '구현'), counts(sum.impl)),
    h('div', { class: 'card' }, h('h3', null, '검증'), counts(sum.verify),
      sum.verified_items_with_unpassed_claims.length ? h('div', { class: 'small muted' }, `그중 ${sum.verified_items_with_unpassed_claims.length}건은 근거 주장이 현재 통과 상태가 아니다`) : null)));
  root.appendChild(h('p', { class: 'small muted' }, '검토함·설계함·구현함·검증함은 서로 다른 상태다. "검증"은 연결된 주장의 시험이 현재 소스에서 통과했을 때만 초록으로 보인다.'));

  const f = S.filter;
  const sel = (key, label, options) => h('label', null, label + ' ',
    h('select', { onchange: (e) => { f[key] = e.target.value; draw(); } },
      [h('option', { value: '' }, '전체')].concat(options.map(([v, t]) => h('option', { value: v, selected: f[key] === v }, t)))));
  const body = h('div');
  const draw = () => {
    const q = f.q.trim().toLowerCase();
    const rows = R.considerations.filter((c) =>
      (!f.layer || c.layer === f.layer) && (!f.applicability || c.applicability === f.applicability) &&
      (!f.verify || c.verify === f.verify || (f.verify === 'open' && c.open)) &&
      (!q || JSON.stringify(c).toLowerCase().includes(q)));
    body.replaceChildren(
      h('p', { class: 'small muted' }, `${rows.length}건`),
      table(['ID', '영역', '고려사항', '적용', '설계', '구현', '검증', '미해결'],
        rows.map((c) => ({ href: '#/item/' + c.id, cells: [idLink(c.id), c.area, c.consideration, statusBadge(c.applicability), statusBadge(c.design), statusBadge(c.impl), verifyBadge(c), c.open ? h('span', { class: 'small' }, c.open) : ''] })), { nowrap: [0, 1] }));
  };
  root.appendChild(h('div', { class: 'filters' },
    sel('layer', '계층', [['general', '일반'], ['domain', 'Rust·LMAX·OMS'], ['project', '프로젝트']]),
    sel('applicability', '적용', [['적용', '적용'], ['조건부', '조건부'], ['비적용', '비적용']]),
    sel('verify', '검증', [['검증', '검증'], ['부분', '부분'], ['미검증', '미검증'], ['해당없음', '해당없음'], ['open', '미해결 사항 있음']]),
    h('input', { type: 'search', placeholder: '검색 (ID, 본문, 출처)', value: f.q, oninput: (e) => { f.q = e.target.value; draw(); } })));
  root.appendChild(body);
  draw();
  return root;
}

function claimRow(id) {
  const c = S.reg.claims.find((x) => x.id === id);
  if (!c) return [id, '', '', ''];
  const ok = c.results.filter((r) => r.result === 'passed').length;
  return { href: '#/claim/' + c.id, cells: [idLink(c.id), c.level, c.statement, claimBadge(c.status), `${ok}/${c.results.length}`] };
}
const claimTable = (ids) => (ids && ids.length ? table(['주장', '수준', '내용', '상태', '시험'], ids.map(claimRow), { nowrap: [0, 1] }) : h('p', { class: 'muted' }, '연결된 주장 없음'));

function screenItem(id) {
  const c = S.reg.considerations.find((x) => x.id === id);
  if (!c) return notFound(id);
  const layer = { general: '일반', domain: 'Rust·LMAX·OMS', project: '프로젝트' }[c.layer];
  const dl = h('dl', { class: 'fields' });
  field(dl, '고려사항', c.consideration);
  field(dl, '필요성', inlineText(c.necessity));
  field(dl, '출처', h('span', { class: 'chips' }, c.sources.map((s) => idLink(s))));
  field(dl, '이 프로젝트에 적용되는가', [statusBadge(c.applicability), ' ', inlineText(c.reason)]);
  field(dl, '처리 방식', inlineText(c.handling));
  field(dl, '상태', h('span', { class: 'chips' }, '설계 ', statusBadge(c.design), ' 구현 ', statusBadge(c.impl), ' 검증 ', verifyBadge(c)));
  field(dl, '미해결 사항', c.open ? inlineText(c.open) : h('span', { class: 'muted' }, '적힌 것 없음'));
  field(dl, '설계 결정', idLinks(c.adr));
  field(dl, '동작 계약', idLinks(c.contracts));
  field(dl, '코드', fileLinks(c.code));
  const un = c.verify === '검증' ? unpassedFor(c.id) : null;
  return h('div', null,
    h('div', { class: 'crumbs' }, h('a', { href: '#/items' }, '고려사항'), ` / ${layer} / ${c.area}`),
    h('h1', null, c.id), dl,
    un ? h('div', { class: 'notice' }, '이 항목은 "검증"으로 적혀 있지만 다음 주장이 현재 통과 상태가 아니다: ', idLinks(un)) : null,
    h('h2', null, '검증 근거'), claimTable(c.claims));
}

async function screenAdr(id) {
  const d = S.reg.decisions.find((x) => x.id === id);
  if (!d) return notFound(id);
  const R = S.reg;
  const dl = h('dl', { class: 'fields' });
  field(dl, '문제', d.problem);
  field(dl, '비교한 대안', h('ul', null, d.alternatives.map((a) => h('li', null, a))));
  field(dl, '선택', d.chosen);
  field(dl, '포기한 것', d.gives_up);
  field(dl, '재검토 조건', d.revisit);
  field(dl, '이 결정이 다루는 고려사항', idLinks(R.considerations.filter((c) => c.adr.includes(id)).map((c) => c.id)));
  field(dl, '이 결정에서 나온 계약', idLinks(R.contracts.filter((c) => c.adr.includes(id)).map((c) => c.id)));
  field(dl, '문서', fileLink(d.file));
  return h('div', null,
    h('div', { class: 'crumbs' }, h('a', { href: '#/items/decisions' }, '설계 결정')),
    h('h1', null, `${d.id} ${d.title}`), dl, h('h2', null, '전문'), await docBlock(d.file));
}

function screenSimple(kind, id) {
  const R = S.reg;
  if (kind === 'assumption') {
    const a = R.assumptions.find((x) => x.id === id);
    if (!a) return notFound(id);
    const dl = h('dl', { class: 'fields' });
    field(dl, '가정', a.statement);
    field(dl, '기대는 대상', a.depends_on);
    field(dl, '근거', inlineText(a.basis));
    field(dl, '깨지면', inlineText(a.if_broken));
    field(dl, '탐지', inlineText(a.detection));
    field(dl, '확인한 범위', inlineText(a.checked));
    return h('div', null, h('div', { class: 'crumbs' }, h('a', { href: '#/items/assumptions' }, '외부 가정')), h('h1', null, a.id), dl);
  }
  if (kind === 'user') {
    const u = R.user_decisions.find((x) => x.id === id);
    if (!u) return notFound(id);
    const dl = h('dl', { class: 'fields' });
    field(dl, '결정이 필요한 이유', inlineText(u.why));
    field(dl, '추천', inlineText(u.recommendation));
    field(dl, '대안', h('ul', null, u.alternatives.map((a) => h('li', null, inlineText(a)))));
    field(dl, '영향', inlineText(u.impact));
    field(dl, '미룰 수 있는 시점', u.defer_until);
    return h('div', null, h('div', { class: 'crumbs' }, h('a', { href: '#/items/user' }, '사용자 결정')), h('h1', null, `${u.id} ${u.title}`), dl);
  }
  const s = R.sources.find((x) => x.id === id);
  if (!s) return notFound(id);
  const dl = h('dl', { class: 'fields' });
  field(dl, '역할', s.role);
  field(dl, '판·시점', s.version);
  field(dl, '읽은 범위', s.accessed);
  field(dl, '주의', s.caution);
  if (s.secondary) field(dl, '2차 자료', s.secondary);
  if (s.detail) field(dl, '상세', fileLink(s.detail));
  field(dl, '이 출처를 쓰는 고려사항', idLinks(R.considerations.filter((c) => c.sources.includes(id)).map((c) => c.id)));
  return h('div', null, h('div', { class: 'crumbs' }, h('a', { href: '#/items/sources' }, '출처')), h('h1', null, `${s.id} — ${s.title}`), dl);
}

// ---------------------------------------------------------------- screen 2: behaviour

function stepChips(steps) {
  const out = [];
  steps.forEach((s, i) => {
    if (i) out.push(h('span', { class: 'arrow' }, '→'));
    out.push(eventChip(s));
  });
  return h('span', { class: 'chips' }, out);
}

function screenBehaviour() {
  const R = S.reg;
  const kindCls = { 정상: 'ok', 오류: 'warn', 장애: 'bad', '순서 역전': 'info', 불일치: 'bad', 운영: 'none' };
  return h('div', null,
    h('h1', null, '동작 탐색'),
    h('p', { class: 'muted' }, [tag('expected'), ' 이 화면은 설계가 정한 동작이다. 실행 중인 노드가 실제로 그렇게 움직였는지는 주문 추적 화면의 기록과 대조한다. 각 단계는 저널 이벤트이고, 누르면 그 이벤트를 정의한 계약·설계 결정·코드·시험으로 간다.']),
    h('h2', null, '정상 경로와 오류 경로'),
    table(['경로', '종류', '이벤트 순서', '설명'],
      R.paths.map((p) => [p.title, badge(kindCls[p.kind] || 'none', p.kind), stepChips(p.steps), inlineText(p.note)])),
    h('h2', null, '동작 계약'),
    h('p', { class: 'small muted' }, '각 계약 문서는 같은 질문에 답한다: 중간에 멈추면 무엇이 남는가, 같은 입력이 다시 오면, 순서가 바뀌면, 누가 언제 변화를 보는가, 외부 결과를 정말 아는가, 복구 뒤 무엇이 다시 실행되는가.'),
    table(['ID', '제목', '요약', '이벤트', '주장'],
      R.contracts.map((c) => ({ href: '#/contract/' + c.id, cells: [idLink(c.id), c.title, c.summary, h('span', { class: 'chips' }, c.events.map(eventChip)), h('span', { class: 'chips' }, c.claims.map((id) => { const cl = R.claims.find((x) => x.id === id); return cl ? claimBadge(cl.status) : null; }))] })), { nowrap: [0] }),
    h('h2', null, '이벤트 색인'),
    table(['이벤트', '정의한 계약'], Object.keys(R.event_index).sort().map((e) => [eventChip(e), idLinks(R.event_index[e])])),
    h('p', { class: 'small' }, '상태 불변식: ', fileLink('docs/04-invariants.md'), ' · 구조: ', fileLink('docs/03-architecture.md'), ' · 계약 목록: ', fileLink('docs/contracts/README.md')));
}

function contractSummary(c) {
  const dl = h('dl', { class: 'fields' });
  field(dl, '요약', c.summary);
  field(dl, '설계 결정 (왜 이렇게)', idLinks(c.adr));
  field(dl, '이벤트', c.events.length ? h('span', { class: 'chips' }, c.events.map(eventChip)) : h('span', { class: 'muted' }, '없음'));
  field(dl, '코드', fileLinks(c.code));
  field(dl, '문서', fileLink(c.file));
  return dl;
}

async function screenContract(id) {
  const c = S.reg.contracts.find((x) => x.id === id);
  if (!c) return notFound(id);
  return h('div', null,
    h('div', { class: 'crumbs' }, h('a', { href: '#/behaviour' }, '동작 탐색'), ' / 계약'),
    h('h1', null, `${c.id} ${c.title}`), contractSummary(c),
    h('h2', null, '무엇으로 확인했는가'), claimTable(c.claims),
    h('h2', null, '전문'), await docBlock(c.file));
}

function screenEvent(name) {
  const R = S.reg;
  const ids = R.event_index[name];
  if (!ids) return notFound(name);
  const paths = R.paths.filter((p) => p.steps.includes(name));
  const root = h('div', null,
    h('div', { class: 'crumbs' }, h('a', { href: '#/behaviour' }, '동작 탐색'), ' / 이벤트'),
    h('h1', null, h('code', null, name)),
    h('p', { class: 'muted' }, [tag('expected'), ' 저널에 이 이벤트가 있으면 아래 계약이 정한 상태 변화가 일어난 것이다. 이벤트의 정의는 ', fileLink('crates/oms-core/src/event.rs'), ', 적용은 ', fileLink('crates/oms-core/src/core.rs'), ', 발생 조건은 ', fileLink('crates/oms-core/src/decide.rs'), '에 있다.']));
  if (paths.length) {
    root.appendChild(h('h2', null, '이 이벤트가 나오는 경로'));
    root.appendChild(table(['경로', '이벤트 순서'], paths.map((p) => [p.title, stepChips(p.steps)])));
  }
  for (const id of ids) {
    const c = R.contracts.find((x) => x.id === id);
    if (!c) continue;
    root.appendChild(h('h2', null, idLink(c.id), ' ', c.title));
    root.appendChild(contractSummary(c));
    root.appendChild(claimTable(c.claims));
  }
  return root;
}

// ---------------------------------------------------------------- screen 3: order traces

function noNode(what) {
  if (S.statusState === 'lost') return h('div', { class: 'notice bad' }, `노드가 응답하지 않는다 (${S.statusError}). 아래에 보이는 값이 있다면 마지막으로 받은 것이고 현재 상태가 아니다.`);
  return h('div', { class: 'notice none' }, `연결되지 않음 (${what}). 실행 중인 노드가 없어 보여 줄 값이 없다. 값이 없는 것이지 정상이라는 뜻이 아니다. `, h('code', null, 'oms-node run --config …'), '으로 띄운 노드의 주소에서 이 화면을 연다.');
}

function ordersTabs(active) {
  return h('div', { class: 'tabs' }, [['orders', '주문'], ['recent', '최근 기록'], ['noops', '이벤트 없는 입력']].map(([k, t]) => h('a', { href: '#/' + (k === 'orders' ? 'orders' : 'recent/' + k), class: k === active ? 'active' : null }, t)));
}

function liveHeader(d, source) {
  return h('p', { class: 'small muted' }, `출처 ${source} · 기준 시각 ${fmtTs(d.as_of)} · 내구 순번 ${d.durable_seq}`);
}

async function screenOrders() {
  const root = h('div', null, h('h1', null, '주문 실행 추적'), ordersTabs('orders'));
  if (S.statusState !== 'live') { root.appendChild(noNode('주문')); return root; }
  const d = await getJson('api/orders?limit=500' + (S.ordersScope === 'open' ? '&scope=open' : ''));
  S.liveKey = JSON.stringify(d.orders) + d.durable_seq;
  const go = h('input', { type: 'search', placeholder: '주문 번호', size: 10, onkeydown: (e) => { if (e.key === 'Enter' && /^\d+$/.test(e.target.value)) location.hash = '#/order/' + e.target.value; } });
  root.appendChild(h('div', { class: 'filters' },
    h('label', null, '범위 ', h('select', { onchange: (e) => { S.ordersScope = e.target.value; route(); } },
      h('option', { value: 'open', selected: S.ordersScope === 'open' }, '미종결'), h('option', { value: 'all', selected: S.ordersScope === 'all' }, '메모리의 전체'))),
    h('label', null, '바로 가기 ', go)));
  root.appendChild(liveHeader(d, '/api/orders (내구화된 기록으로 만든 읽기 모델)'));
  root.appendChild(h('p', { class: 'small muted' }, [tag('observed'), ` 메모리에 ${d.total_in_memory}건, 최근 것부터 ${d.orders.length}건. 종결 후 보존 기간이 지난 주문은 메모리에서 빠진다. 그런 주문은 `, h('code', null, 'oms-node trace --data-dir … --order N'), '으로 저널에서 찾는다.']));
  root.appendChild(table(['번호', '전략', '키', '종목', '방향', { t: '수량', cls: 'num' }, { t: '가격', cls: 'num' }, '단계', { t: '체결', cls: 'num' }, { t: '예약', cls: 'num' }, '표시', '접수 시각', '종결'],
    d.orders.map((o) => ({ href: '#/order/' + o.id, cells: [o.id, o.strategy, o.client_order_id, o.instrument, o.side, o.qty, o.px, phaseBadge(o.phase), o.cum_qty, o.reserved,
      [o.in_doubt ? badge('bad', '결과 불명') : null, o.cancel_requested ? badge('info', '취소 요청') : null], fmtTs(o.accepted_at), o.closed ? JSON.stringify(o.closed.reason || o.closed) : ''] }))));
  return root;
}
function phaseBadge(p) {
  const cls = { pending_send: 'warn', working: 'ok', closing: 'info', closed: 'none' }[p] || 'none';
  return badge(cls, p);
}

function traceEntry(t, focusOrder) {
  const R = S.reg;
  const rec = t.record;
  const inName = inputName(rec.input);
  const key = 'r' + rec.seq;
  const evRows = rec.events.map((e, i) => {
    const name = evName(e);
    const body = evBody(e);
    const own = body && body.order_id !== undefined ? body.order_id === focusOrder : null;
    const contracts = R.event_index[name] || [];
    return h('div', { class: 'row' },
      eventChip(name),
      own === false ? h('span', { class: 'muted small' }, `(주문 ${body.order_id})`) : null,
      h('span', { class: 'chips small' }, '계약', contracts.map((c) => idLink(c))),
      body ? details(`${key}e${i}`, '내용', pre(body)) : null);
  });
  return h('div', { class: 'entry' },
    h('div', { class: 'head' },
      h('span', { class: 'seq' }, '#' + rec.seq),
      h('span', null, '입력 시각 ', h('span', { class: 'mono' }, fmtTs(rec.at))),
      h('span', null, '내구 확인 ', h('span', { class: 'mono' }, fmtTs(t.durable_at))),
      h('span', { class: 'small muted' }, `큐 ${fmtDur(t.queue_us)} · 판단 ${fmtDur(t.core_us)} · 기록 ${fmtDur(t.persist_us)}`)),
    h('div', { class: 'row' }, h('span', { class: 'label' }, '입력'), tag('observed'), h('span', { class: 'chip' }, inName), details(key + 'in', '내용', pre(rec.input))),
    h('div', { class: 'row' }, h('span', { class: 'label' }, '이벤트'), tag('observed'), h('span', { class: 'small muted' }, '이 입력으로 코어가 결정해 저널에 남긴 것')),
    evRows,
    h('div', { class: 'row' }, h('span', { class: 'label' }, '내구화 뒤'), tag('observed'),
      t.reply ? h('span', null, '응답 ', h('code', null, JSON.stringify(t.reply))) : h('span', { class: 'muted small' }, '응답 없음'),
      t.commands.length ? h('span', null, ' · 게이트웨이 명령 ', t.commands.map((c, i) => [h('span', { class: 'chip' }, evName(c)), details(`${key}c${i}`, '내용', pre(c))])) : h('span', { class: 'muted small' }, ' · 게이트웨이 명령 없음')));
}

async function screenOrder(id) {
  const root = h('div', null, h('div', { class: 'crumbs' }, h('a', { href: '#/orders' }, '주문 실행 추적')), h('h1', null, '주문 ' + id));
  if (S.statusState !== 'live') { root.appendChild(noNode('주문 추적')); return root; }
  let d;
  try {
    d = await getJson('api/orders/' + encodeURIComponent(id));
  } catch (e) {
    root.appendChild(h('div', { class: 'notice none' }, e.status === 404
      ? ['이 주문은 읽기 모델에 없다. 없는 번호이거나, 종결 후 보존 기간이 지나 메모리에서 빠졌다. 저널에는 남아 있다: ', h('code', null, `oms-node trace --data-dir … --order ${id}`)]
      : String(e.message)));
    return root;
  }
  S.liveKey = JSON.stringify(d.trace ? d.trace.length : 0) + JSON.stringify(d.order);
  const o = d.order;
  root.appendChild(liveHeader(d, '/api/orders/' + id));
  const facts = h('dl', { class: 'kv' });
  const kv = (k, v) => { facts.appendChild(h('dt', null, k)); facts.appendChild(h('dd', null, v)); };
  kv('전략 / 키', `${o.strategy} / ${o.client_order_id}`);
  kv('주문', `${o.instrument} ${o.side} ${o.qty} @ ${o.px} ${o.tif}${o.reduce_only ? ' reduce-only' : ''}`);
  kv('단계', phaseBadge(o.phase));
  kv('체결 / 예약', `${o.cum_qty} / ${o.reserved}`);
  kv('거래소로 보낸 식별자', h('code', null, d.venue_client_id));
  kv('거래소 주문 ID', o.venue_oid === null ? h('span', { class: 'muted' }, '모른다') : String(o.venue_oid));
  kv('만료 시각', fmtTs(o.expires_at));
  kv('종결', o.close ? h('code', null, JSON.stringify(o.close)) : h('span', { class: 'muted' }, '미종결'));
  const unknown = h('div', { class: 'card unknown' }, h('h3', null, tag('unknown'), ' 이 화면이 알 수 없는 것'));
  const ul = h('ul');
  if (o.doubt) ul.appendChild(h('li', null, h('b', null, '전송 결과 불명. '), `이 주문이 거래소에 놓였는지 모른다 (${o.doubt.reason}: ${o.doubt.detail}). 다시 보내지 않는다. 조회로 발견되거나, 만료 시각 + 여유가 지난 뒤 조회에서 없다고 나오면 해소된다. `, idLink('C-DOUBT')));
  ul.appendChild(h('li', null, '거래소가 지금 이 주문을 어떤 상태로 갖고 있는지. 아래 기록은 OMS가 받아 저널에 적은 통보와 조회 결과까지다.'));
  ul.appendChild(h('li', null, '아직 내구화되지 않은 변화. 이 화면은 저널에 쓰인 기록만 보여 준다.'));
  if (!o.close) ul.appendChild(h('li', null, '아직 도착하지 않은 체결이 있는지. 종결은 체결 동기화가 종결 시각을 지난 뒤에 확정된다. ', idLink('C-TERM')));
  unknown.appendChild(ul);
  root.appendChild(h('div', { class: 'two' },
    h('div', { class: 'card' }, h('h3', null, tag('observed'), ' 저널 기록으로 만든 현재 상태'), facts, details('orderjson', '주문 상태 전체', pre(o))),
    unknown));
  root.appendChild(h('h2', null, '기록 순서'));
  root.appendChild(h('p', { class: 'small muted' }, '순서는 저널 순번이다. 시각은 참고용이다: 입력 시각과 내구 확인 시각은 이 호스트의 시계이고, 이벤트 안의 거래소 시각과 직접 비교할 수 없다. 시각이 가깝다는 것만으로 원인과 결과라고 판단하지 않는다.'));
  if (d.trace_truncated) root.appendChild(h('div', { class: 'notice' }, '이 주문의 기록이 200건을 넘어 오래된 것 일부를 화면에서 뺐다. 저널에는 전부 있다.'));
  if (!d.trace) root.appendChild(h('div', { class: 'notice none' }, '이 프로세스가 시작된 뒤 이 주문에 대한 기록이 없다. 재시작 전의 기록은 화면에 싣지 않는다. 저널에서 본다: ', h('code', null, `oms-node trace --data-dir … --order ${id}`)));
  else root.appendChild(h('div', { class: 'trace' }, d.trace.map((t) => traceEntry(t, o.id))));
  return root;
}

async function screenRecent(which) {
  const root = h('div', null, h('h1', null, '주문 실행 추적'), ordersTabs(which));
  if (S.statusState !== 'live') { root.appendChild(noNode('기록')); return root; }
  const d = await getJson('api/recent?limit=200');
  S.liveKey = String(d.durable_seq) + d.inputs_without_events.length;
  root.appendChild(liveHeader(d, '/api/recent'));
  if (which === 'noops') {
    root.appendChild(h('div', { class: 'notice' }, [tag('observed'), ' 상태를 바꾸지 않은 입력(중복 요청, 중복 통보 등)이다. 저널에 남지 않고 최근 500건만 메모리에 둔다. ', h('b', null, '여기 없다는 것은 아무것도 증명하지 않는다.')]));
    root.appendChild(table(['시각', '입력', '응답', '내용'], d.inputs_without_events.map((n, i) => [fmtTs(n.at), h('span', { class: 'chip' }, inputName(n.input)), n.reply ? h('code', null, JSON.stringify(n.reply)) : '', details('n' + i + n.at, '내용', pre(n.input))]), { nowrap: [0] }));
    return root;
  }
  root.appendChild(h('p', { class: 'small muted' }, [tag('observed'), ' 최근 저널 기록 200건(최신 먼저). 이 프로세스가 시작된 뒤의 것만 있다.']));
  root.appendChild(h('div', { class: 'trace' }, d.records.map((t) => traceEntry(t, null))));
  return root;
}

// ---------------------------------------------------------------- screen 4: verification

function screenVerify() {
  const R = S.reg;
  const E = S.evidence;
  const root = h('div', null, h('h1', null, '검증 현황'));
  root.appendChild(h('p', { class: 'muted' }, '주장의 상태는 결과 파일에서 계산한다. 통과는 "그 시험이 그 소스에서 통과했다"는 뜻이고, 주장이 다루지 않는 범위는 각 주장의 "검증하지 않은 것"에 있다.'));
  if (!E) root.appendChild(h('div', { class: 'notice bad' }, '수용 시험 결과 파일이 없다. 모든 주장이 미실행이다. ', h('code', null, 'cargo run --release -p xtask -- verify && cargo run --release -p xtask -- docs')));
  else {
    const stale = E.source_digest !== R.source_digest;
    const failed = E.suites.filter((s) => !s.ok);
    root.appendChild(h('div', { class: 'notice ' + (stale || failed.length ? 'bad' : 'info') },
      `수용 시험: ${E.mode === 'quick' ? '축약' : '전체'} · ${fmtTs(E.started_at_us)} ~ ${fmtTs(E.finished_at_us)} · 소스 ${E.source_digest}`,
      stale ? ` — 현재 소스(${R.source_digest})와 다르다. 이 결과는 이전 버전의 것이다.` : ' — 현재 소스와 같다.',
      failed.length ? ` 실패한 묶음: ${failed.map((s) => s.name).join(', ')}` : '',
      E.live_testnet ? ' · 실제 testnet 읽기 전용 시험 포함' : ' · 실제 거래소 시험은 실행하지 않았다'));
  }
  root.appendChild(h('div', { class: 'notice' }, [h('b', null, '이 검증이 확인하지 않은 것. '),
    '실제 전원 장애(프로세스 강제 종료는 OS 캐시를 잃지 않는다). 실제 거래소에서의 주문·취소·체결(가상 거래소와 읽기 전용 조회만 했다). 장시간 운용. 다른 하드웨어. ',
    '가상 거래소는 이 설계가 문서에서 읽은 대로 만든 것이므로, 문서를 잘못 읽었다면 같은 오해를 공유한다.']));

  const cs = R.summary.claims_by_status;
  const failedClaims = R.claims.filter((c) => c.status === 'failed');
  if (failedClaims.length) {
    root.appendChild(h('div', { class: 'notice bad' }, h('b', null, `실패한 주장 ${failedClaims.length}건. `),
      failedClaims.map((c) => h('div', null, idLink(c.id), ' ', c.statement, ' — ', c.results.filter((r) => r.result === 'failed').map((r) => r.detail || r.test).join('; ')))));
  }
  root.appendChild(h('h2', null, '주장'));
  const body = h('div');
  const draw = () => {
    const rows = R.claims.filter((c) => !S.claimFilter || c.status === S.claimFilter);
    body.replaceChildren(table(['ID', '수준', '주장', '실제로 실행한 것', '모의한 것', '상태', '시험'],
      rows.map((c) => {
        const ok = c.results.filter((r) => r.result === 'passed').length;
        return { href: '#/claim/' + c.id, cells: [idLink(c.id), c.level, c.statement, c.real, c.simulated, claimBadge(c.status), `${ok}/${c.results.length}`] };
      }), { nowrap: [0, 1] }));
  };
  root.appendChild(h('div', { class: 'filters' }, h('label', null, '상태 ',
    h('select', { onchange: (e) => { S.claimFilter = e.target.value; draw(); } },
      h('option', { value: '' }, `전체 ${R.claims.length}`),
      Object.entries(cs).map(([k, v]) => h('option', { value: k, selected: S.claimFilter === k }, `${(CLAIM_STATUS[k] || [0, k])[1]} ${v}`))))));
  root.appendChild(body);
  draw();

  const un = R.summary.verified_items_with_unpassed_claims;
  if (un.length) {
    root.appendChild(h('h2', null, '"검증"으로 적혔지만 근거가 통과 상태가 아닌 항목'));
    root.appendChild(table(['항목', '통과하지 않은 주장'], un.map((x) => [idLink(x.item), idLinks(x.claims_not_passed)])));
  }

  if (E) {
    root.appendChild(h('h2', null, '시험 묶음'));
    root.appendChild(table(['묶음', '무엇을', '결과', { t: '시험 수', cls: 'num' }, { t: '초', cls: 'num' }, '명령', '로그'],
      E.suites.map((s) => [s.name, s.what, s.ok ? badge('ok', '통과') : badge('bad', `실패 (${s.exit_code})`), s.tests.length, s.seconds, h('code', null, s.command), h('span', { class: 'mono small' }, s.log)])));
    root.appendChild(details('env', '실행 환경', jv(E.environment)));
  }

  root.appendChild(h('h2', null, '시험이 정말 잡는지: 고의로 고장 낸 코드'));
  const M = S.mutants;
  if (!M) root.appendChild(h('div', { class: 'notice none' }, '변이 점검 결과 파일이 없다. ', h('code', null, 'cargo run --release -p xtask -- mutants')));
  else {
    const stale = M.source_digest !== R.source_digest;
    const survived = M.mutants.filter((m) => !m.killed);
    root.appendChild(h('p', { class: 'small muted' }, `${fmtTs(M.taken_at_us)} · 소스 ${M.source_digest}${stale ? ' (현재 소스와 다르다)' : ''} · ${M.mutants.length}건 중 ${M.mutants.length - survived.length}건을 시험이 잡았다. 선택한 지점만 고장 낸 것이고 전체 코드에 대한 변이 시험이 아니다.`));
    root.appendChild(table(['ID', '고장 낸 내용', '지키는 성질', '시험', '결과', '비고'],
      M.mutants.map((m) => [m.id, m.what, inlineText(m.guards), h('code', null, m.test || ''), m.killed ? badge('ok', '잡음') : badge('bad', '못 잡음'), m.note || '']), { nowrap: [0] }));
  }

  root.appendChild(h('h2', null, '성능 측정'));
  root.appendChild(h('p', { class: 'small muted' }, '지연은 "보내려던 시각 → 응답"으로 잰다(부하 생성기가 밀려도 기다린 시간이 빠지지 않는다). 가상 거래소를 같은 호스트에 둔 측정이며 실제 거래소 왕복 시간은 들어 있지 않다. 조건과 해석: ', fileLink('docs/performance/README.md')));
  if (!S.perf.length) root.appendChild(h('div', { class: 'notice none' }, '성능 결과 파일이 없다.'));
  for (const p of S.perf) {
    root.appendChild(h('h3', null, p.label, ' ', h('span', { class: 'small muted' }, `${fmtTs(p.taken_at_us)} · ${p.build || ''}`)));
    if (p.runs) {
      root.appendChild(h('p', { class: 'small' }, `${p.commit_layout} · ${p.durability} · ${p.venue} · 연결 ${p.connections} · 구간당 ${p.seconds_per_rate}초 · 한도: ${p.limits || '기록 없음'}`));
      root.appendChild(table([{ t: '요청/초', cls: 'num' }, { t: '달성', cls: 'num' }, { t: '보냄', cls: 'num' }, { t: '접수', cls: 'num' }, { t: '오류(종류별)·무응답', cls: 'num' }, { t: 'p50', cls: 'num' }, { t: 'p99', cls: 'num' }, { t: 'p99.9', cls: 'num' }, { t: '최대', cls: 'num' }, { t: '생성기 지연 p99', cls: 'num' }, { t: 'fdatasync p99', cls: 'num' }, { t: '큐 최고 수위 (거래소/제어/주문)', cls: 'num' }],
        p.runs.map((r) => {
          const l = r.load;
          const lat = l.latency_intended_to_response;
          const errs = Object.entries(l.errors || {}).map(([k, v]) => `${k} ${v}`).concat(l.unanswered ? [`무응답 ${l.unanswered}`] : []).join(', ') || '0';
          return [l.offered_rate, l.achieved_rate, l.sent, l.accepted, errs, fmtDur(lat.p50), fmtDur(lat.p99), fmtDur(lat.p999), fmtDur(lat.max), fmtDur(l.generator_lag.p99), r.stage_us && r.stage_us.sync ? fmtDur(r.stage_us.sync.p99_us) : '—', r.queues ? r.queues.high_water.join(' / ') : '—'];
        })));
    } else {
      const { environment, label, taken_at_us, build, node_config, ...rest } = p;
      root.appendChild(jv(rest));
    }
    if (p.node_config) root.appendChild(details('perfcfg' + p.label, '이 측정의 노드 설정 전문', pre(p.node_config)));
    root.appendChild(details('perfenv' + p.label, '측정 환경', jv(p.environment)));
  }
  return root;
}

function screenClaim(id) {
  const R = S.reg;
  const c = R.claims.find((x) => x.id === id);
  if (!c) return notFound(id);
  const dl = h('dl', { class: 'fields' });
  field(dl, '주장', c.statement);
  field(dl, '상태', claimBadge(c.status));
  field(dl, '수준', c.level);
  field(dl, '검증 범위', inlineText(c.scope));
  field(dl, '실제로 실행한 것', inlineText(c.real));
  field(dl, '모의한 것', inlineText(c.simulated));
  field(dl, '주입한 장애', inlineText(c.faults));
  field(dl, '판정 기준', inlineText(c.criterion));
  field(dl, '검증하지 않은 것', inlineText(c.not_covered));
  field(dl, '재현', h('code', null, c.repro));
  field(dl, '뒷받침하는 것', inlineText(c.supports));
  field(dl, '이 주장에 기대는 고려사항', idLinks(R.considerations.filter((x) => x.claims.includes(id)).map((x) => x.id)));
  field(dl, '이 주장에 기대는 계약', idLinks(R.contracts.filter((x) => x.claims.includes(id)).map((x) => x.id)));
  return h('div', null,
    h('div', { class: 'crumbs' }, h('a', { href: '#/verify' }, '검증 현황'), ' / 주장'),
    h('h1', null, c.id), dl,
    h('h2', null, '시험별 결과'),
    table(['시험 (묶음/이름)', '결과', '비고'], c.results.map((r) => [h('span', { class: 'mono' }, r.test), resultBadge(r.result), r.detail || ''])));
}

// ---------------------------------------------------------------- screen 5: operations

function histRow(name, s) {
  return [name, s.count, fmtDur(s.mean_us), fmtDur(s.p50_us), fmtDur(s.p90_us), fmtDur(s.p99_us), fmtDur(s.p999_us), fmtDur(s.max_us)];
}

function screenOps() {
  const root = h('div', null, h('h1', null, '운영 상태'));
  const st = S.status;
  if (!st) { root.appendChild(noNode('운영 상태')); return root; }
  if (S.statusState === 'lost') root.appendChild(noNode('운영 상태'));
  S.liveKey = String(st.as_of);
  const core = st.core;
  const j = st.journal;
  if (st.fatal) root.appendChild(h('div', { class: 'notice bad' }, h('b', null, '치명 상태. '), st.fatal, ' — 새 입력을 받지 않는다. 절차: ', fileLink('docs/operations/runbook.md')));
  root.appendChild(h('p', { class: 'small muted' }, `출처 /api/status · 기준 시각 ${fmtTs(st.as_of)} · 2초마다 다시 읽는다 · pid ${st.node.pid} · 시작 ${fmtTs(st.node.started_at)} · 인스턴스 ${core.instance_id} · 부팅 ${core.boot} · 설정 v${core.config_version}`));

  const card = (title, cls, ...kids) => h('div', { class: 'card ' + (cls || '') }, h('h3', null, title), kids);
  const kvs = (pairs) => h('dl', { class: 'kv' }, pairs.map(([k, v]) => [h('dt', null, k), h('dd', null, v)]));
  const holds = core.holds || [];
  const hold = (x) => badge('bad', typeof x === 'string' ? x : JSON.stringify(x));

  const cards = h('div', { class: 'cards' });
  cards.appendChild(card(['신규 주문 ', tag('inferred')], holds.length ? 'alert' : '',
    holds.length ? [h('p', null, h('b', null, '계좌 전체가 막혀 있다: '), h('span', { class: 'chips' }, holds.map(hold)))] : h('p', null, badge('ok', '계좌 차단 사유 없음')),
    h('p', { class: 'small muted' }, '차단 사유는 저장된 값이 아니라 현재 상태에서 계산한다. 체결 기장·취소·대조는 차단과 무관하게 계속된다. ', idLink('ADR-008')),
    Object.entries(st.strategies).map(([name, s]) => h('div', { class: 'small' }, h('b', null, name), ' ', s.holds.length ? h('span', { class: 'chips' }, s.holds.map(hold)) : badge('ok', '받는다'), ` · 열린 주문 ${s.open_orders}`))));

  cards.appendChild(card(['거래소 연결 ', tag('observed')], core.link.up ? '' : 'alert',
    kvs([
      ['링크', core.link.up ? badge('ok', `연결 (세션 ${core.link.session})`) : badge('bad', `단절 (마지막 세션 ${core.link.session})`)],
      ['체결 확인', `세션 ${core.sync.fills_session}, ${fmtTs(core.sync.fills_up_to)}까지`],
      ['열린 주문 확인', `세션 ${core.sync.open_orders_session}`],
      ['포지션 확인', `세션 ${core.sync.positions_session}`],
    ]),
    h('p', { class: 'small muted' }, '게이트웨이가 보고한 것을 저널에 적은 값이다. 세 확인의 세션이 현재 세션과 같아야 재확인이 끝난 것이다. ', idLink('C-LINK'))));

  cards.appendChild(card(['지금 필요한 조회 ', tag('inferred')], '',
    core.needs.length ? h('ul', null, core.needs.slice(0, 20).map((n) => h('li', { class: 'small mono' }, JSON.stringify(n)))) : h('p', { class: 'muted' }, '없음'),
    core.needs.length > 20 ? h('p', { class: 'small muted' }, `외 ${core.needs.length - 20}건`) : null,
    h('p', { class: 'small muted' }, '대조기가 이 목록을 보고 거래소에 묻는다. ', idLink('C-RECON'))));

  cards.appendChild(card(['결과 불명 주문 ', tag('observed')], core.in_doubt.length ? 'alert' : '',
    core.in_doubt.length ? table(['주문', '전략', '내용', '사유', '언제부터', '만료'], core.in_doubt.map((d) => ({ href: '#/order/' + d.order_id, cells: [d.order_id, d.strategy, `${d.instrument} ${d.side} ${d.qty}`, `${d.reason}: ${d.detail}`, fmtTs(d.since), fmtTs(d.expires_at)] }))) : h('p', { class: 'muted' }, '없음'),
    h('p', { class: 'small' }, tag('unknown'), ' 이 주문들이 거래소에 있는지는 모른다. 다시 보내지 않는다. ', idLink('C-DOUBT'))));

  cards.appendChild(card(['확인되지 않은 불일치 ', tag('observed')], core.mismatches_unacked.length ? 'alert' : '',
    core.mismatches_unacked.length ? table(['번호', '종류', '대상', '내용', '제기'], core.mismatches_unacked.map((m) => [m.id, typeof m.kind === 'string' ? m.kind : JSON.stringify(m.kind), m.subject, m.detail, fmtTs(m.raised_at)])) : h('p', { class: 'muted' }, '없음'),
    h('p', { class: 'small muted' }, '운영자가 원인을 확인하고 ', h('code', null, 'omsctl --socket …/admin.sock ack --id N --note …'), '로 닫는다. ', idLink('C-MISMATCH'))));

  cards.appendChild(card(['저널 ', tag('observed')], st.journal.last_snapshot_error ? 'alert' : '',
    kvs([
      ['내구 순번', String(j.durable_seq)],
      ['마지막 커밋', j.last_commit_at ? `${fmtTs(j.last_commit_at)} (${fmtDur(j.last_commit_age_us)} 전)` : '이 프로세스에서는 아직 없음'],
      ['마지막 write+fdatasync', fmtDur(j.last_sync_us)],
      ['이 프로세스가 쓴 양', `${(j.bytes_written / 1048576).toFixed(2)} MiB`],
      ['마지막 스냅샷', j.last_snapshot_seq ? `순번 ${j.last_snapshot_seq}, ${fmtTs(j.last_snapshot_at)}` : '이 프로세스에서는 아직 없음'],
      ['스냅샷 이후 기록', String(j.records_since_snapshot)],
      ['스냅샷 오류', j.last_snapshot_error || '없음'],
      ['저장 공간 부족', core.storage_low ? badge('bad', '예: 신규 주문 차단') : badge('ok', '아니오')],
    ]),
    h('p', { class: 'small muted' }, '입력이 없으면 커밋도 없다. 마지막 커밋이 오래됐다는 것만으로는 이상이 아니다. ', idLink('C-JOURNAL'))));

  cards.appendChild(card(['주문 수 ', tag('observed')], '',
    kvs([
      ['미종결', String(core.open_orders)],
      ['전송 대기 / 작동 중 / 종결 대기', `${core.pending_send} / ${core.working} / ${core.closing}`],
      ['거래소 증거를 기다리는 전송', String(core.inflight_sends)],
      ['대기 체결', String(core.parked_fills)],
      ['메모리의 주문', String(core.orders_in_memory)],
      ['운영자 중지', core.operator_halt_account ? '계좌' : (Object.keys(core.operator_halt_strategy || {}).length ? JSON.stringify(core.operator_halt_strategy) : '없음')],
    ]),
    h('p', { class: 'small muted' }, [tag('expected'), ' 상한은 설정의 ', h('code', null, '[core.policy]'), '에 있다. ', idLink('C-OVERLOAD')])));

  cards.appendChild(card([tag('unknown'), ' 이 화면이 알 수 없는 것'], 'unknown',
    h('ul', { class: 'small' },
      h('li', null, `거래소의 현재 실제 상태. 아는 것은 마지막 대조까지다 (체결: ${fmtTs(core.sync.fills_up_to)}).`),
      h('li', null, '저널에 아직 쓰이지 않은 변화. 코어가 저널보다 앞서 있는 정도는 큐 깊이로만 짐작한다.'),
      h('li', null, '전원 장애 뒤 디스크에 무엇이 남는지. 저장 장치가 flush 요청을 지키는지는 확인하지 않았다. ', idLink('A-05')),
      h('li', null, '이 호스트의 시계가 거래소 시계와 얼마나 다른지.'),
      h('li', null, '이 프로세스가 죽으면 이 화면은 갱신되지 않는다. 상단의 "브라우저와의 차이"를 본다. 알림은 없다. ', idLink('U-11')))));
  root.appendChild(cards);

  const q = st.pipeline.queues;
  root.appendChild(h('h2', null, '입력 큐'));
  root.appendChild(table(['큐', { t: '깊이 (관측)', cls: 'num' }, '', { t: '상한 (기대)', cls: 'num' }, { t: '최고 수위', cls: 'num' }, { t: '받음', cls: 'num' }, { t: '거절', cls: 'num' }, '가득 차면'],
    st.pipeline.queue_lanes.map((name, i) => [name, q.depth[i], h('meter', { min: 0, max: q.capacity[i], high: Math.floor(q.capacity[i] * 0.8), value: q.depth[i] }), q.capacity[i], q.high_water[i], q.accepted[i], q.refused[i],
      { venue: '게이트웨이가 기다린다 (버리지 않는다)', control: '거절한다 (overloaded)', orders: '거절한다 (overloaded)' }[name] || ''])));
  root.appendChild(h('p', { class: 'small muted' }, `빈도 한도로 거절 ${st.pipeline.ingress_rate_limited} · 큐가 차서 거절 ${st.pipeline.ingress_refused_overload} (프로세스 시작 이후)`));

  root.appendChild(h('h2', null, ['단계별 지연 ', tag('observed')]));
  const sg = st.pipeline.stage_us;
  root.appendChild(table(['단계', { t: '표본', cls: 'num' }, { t: '평균', cls: 'num' }, { t: 'p50', cls: 'num' }, { t: 'p90', cls: 'num' }, { t: 'p99', cls: 'num' }, { t: 'p99.9', cls: 'num' }, { t: '최대', cls: 'num' }],
    [histRow('큐 대기', sg.queue), histRow('판단 (Core::handle)', sg.core), histRow('판단 끝 → 내구', sg.persist), histRow('입력 → 내구', sg.total), histRow('write + fdatasync 한 번', sg.sync)]));
  root.appendChild(h('p', { class: 'small muted' }, `커밋당 기록 수: 평균 ${sg.batch.mean_us}, 최대 ${sg.batch.max_us}. 히스토그램 버킷 때문에 값은 최대 12.5% 크게 보일 수 있다. 프로세스 시작 이후 전체를 센다(표본 추출 없음).`));

  const bookTable = (books) => {
    const names = Object.keys(books || {});
    if (!names.length) return h('p', { class: 'muted' }, '없음');
    return table(['종목', { t: '포지션', cls: 'num' }, { t: '매수 미체결', cls: 'num' }, { t: '매도 미체결', cls: 'num' }, { t: '열린 주문', cls: 'num' }, { t: '거래 수량', cls: 'num' }, { t: '거래 금액', cls: 'num' }, { t: '수수료', cls: 'num' }, { t: '체결 수', cls: 'num' }],
      names.map((n) => { const b = books[n]; return [n, b.pos, b.buy_open, b.sell_open, b.open_orders, b.traded_qty, b.traded_notional, b.fees, b.fills]; }));
  };
  root.appendChild(h('h2', null, ['장부 ', tag('observed')]));
  root.appendChild(h('p', { class: 'small muted' }, '저널에 기장된 체결과 예약에서 나온 값이다. 거래소의 포지션과 같다는 보장은 포지션 대조가 통과한 시점까지다. 자금 조달·청산·수동 거래는 반영되지 않는다(외부 체결로 탐지되면 불일치가 뜬다).'));
  root.appendChild(h('h3', null, '계좌'));
  root.appendChild(bookTable(st.account));
  if (st.unattributed && Object.keys(st.unattributed).length) { root.appendChild(h('h3', null, '어느 전략에도 속하지 않는 분')); root.appendChild(bookTable(st.unattributed)); }
  for (const [name, s] of Object.entries(st.strategies)) { root.appendChild(h('h3', null, '전략 ' + name)); root.appendChild(bookTable(s.books)); }

  root.appendChild(h('h2', null, '이번 시작의 복구'));
  root.appendChild(jv(st.node.recovery));
  root.appendChild(h('h2', null, '계수기'));
  root.appendChild(h('div', { class: 'two' }, h('div', null, h('h3', null, '코어 (저널 기준, 재시작해도 이어진다)'), jv(core.stats)), h('div', null, h('h3', null, '파이프라인 (프로세스 시작 이후)'), jv(st.pipeline.stats))));
  root.appendChild(h('p', { class: 'small' }, '운영 절차: ', fileLink('docs/operations/runbook.md')));
  return root;
}

